WITH lines AS (SELECT id, created_at, attr_key, value FROM carts LATERAL VIEW EXPLODE(attributes) x AS attr_key, value) SELECT id, created_at, attr_key, value, LAST_VALUE(attr_key, TRUE) OVER (PARTITION BY attr_key ORDER BY created_at, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_attr_key, ROW_NUMBER() OVER (ORDER BY created_at, id, attr_key) AS event_seq FROM lines;
